"""m02 ORIGINAL questions, part 3: Cengel Chapter 9 end-of-chapter problems with printed answers (9-16, 9-19, 9-23, 9-34, 9-59, 9-76, 9-84, 9-96, 9-98, 9-110, 9-119, 9-147, 9-150)."""
import math
from scipy.optimize import brentq
from m02_common import *
import gen_m02_orig as G
from gen_m02_orig import MC, ES, pr, srcB, num, T_CARNOT, T_OTTO, T_DIESEL, T_BRAY, T_REAL, T_REGEN, T_MULTI, T_JET, T_OTHER
def sq(a, b): return B(a, b)
def CP(n): return srcB(f'Cengel Bài {n}', f'Cengel Problem {n}')

def build():
    # ---------------------------------------------------------------- 9-23 Carnot, variable cp
    c = carnot_var(350, 1200, 150, 300); mass = 0.5 / c['wnet']; Qin = mass * c['qin']
    pc = dict(TL=350, TH=1200, P1=150, P2=300, Wnet=0.5)
    for k_ in ('Pmax', 'qin', 'wnet'): reg('carnot_v', pc, k_, c[k_], 2e-3)
    reg('carnot_v', pc, 'Qin', Qin, 2e-3); reg('carnot_v', pc, 'm', mass, 2e-3)
    pr('9-23 Pmax', c['Pmax'], 30013, 1e-4, 'Cengel 9–23'); pr('9-23 Qin', Qin, 0.706, 2e-3, 'Cengel 9–23'); pr('9-23 m', mass, 0.00296, 2e-3, 'Cengel 9–23')
    MC(B('Chu trình Carnot không khí khép kín giữa 350 K và 1200 K; áp suất trước và sau nén đẳng nhiệt là 150 và 300 kPa; công thực mỗi chu trình 0,5 kJ; nhiệt dung riêng thay đổi. Áp suất cực đại (kPa) và nhiệt cấp vào (kJ) lần lượt là:', 'A closed air Carnot cycle between 350 K and 1200 K; the pressures before and after the isothermal compression are 150 and 300 kPa; net work 0.5 kJ per cycle; variable specific heats. The maximum pressure (kPa) and the heat added (kJ) are, respectively:'),
       [sq(f'{N(c["Pmax"],0)} kPa và {N(Qin,3)} kJ', f'{N(c["Pmax"],0)} kPa and {N(Qin,3)} kJ'), sq(f'{N(300*(1200/350)**3.5,0)} kPa và {N(Qin,3)} kJ', f'{N(300*(1200/350)**3.5,0)} kPa and {N(Qin,3)} kJ'), sq(f'{N(c["Pmax"],0)} kPa và {N(0.5,3)} kJ', f'{N(c["Pmax"],0)} kPa and {N(0.5,3)} kJ'), sq(f'{N(c["Pmax"]*2,0)} kPa và {N(mass*c["qout"],3)} kJ', f'{N(c["Pmax"]*2,0)} kPa and {N(mass*c["qout"],3)} kJ')], 0,
       B(f'Đẳng entropi 350 → 1200 K: P_max = P₂·P_r(1200)/P_r(350) = 300·{N(A(1200,"Pr"),1)}/{N(A(350,"Pr"),3)} = {N(c["Pmax"],0)} kPa (sách 30 013). Δs = R ln(300/150) = {N(c["ds"],4)} kJ/kg·K; q_in = T_HΔs = {N(c["qin"],1)} kJ/kg; w_net = (T_H − T_L)Δs = {N(c["wnet"],1)} ⇒ m = 0,5/{N(c["wnet"],1)} = {N(mass,5)} kg; Q_in = m q_in = {N(Qin,3)} kJ. Giá trị {N(300*(1200/350)**3.5,0)} kPa dùng k = 1,4 thay vì bảng; 0,5 kJ là công thực; {N(mass*c["qout"],3)} kJ là nhiệt thải.',
         f'Isentropic 350 → 1200 K: P_max = P₂·P_r(1200)/P_r(350) = 300·{N(A(1200,"Pr"),1)}/{N(A(350,"Pr"),3)} = {N(c["Pmax"],0)} kPa (book 30,013). Δs = R ln(300/150) = {N(c["ds"],4)} kJ/kg·K; q_in = T_HΔs = {N(c["qin"],1)} kJ/kg; w_net = (T_H − T_L)Δs = {N(c["wnet"],1)} ⇒ m = 0.5/{N(c["wnet"],1)} = {N(mass,5)} kg; Q_in = m q_in = {N(Qin,3)} kJ. The value {N(300*(1200/350)**3.5,0)} kPa uses k = 1.4 instead of the table; 0.5 kJ is the net work; {N(mass*c["qout"],3)} kJ is the rejected heat.'),
       3, T_CARNOT, CP('9–23'), 'printed answer Cengel 9–23 + script (slide tr.11–13)')

    # ---------------------------------------------------------------- 9-16 and 9-19 (non-standard cycles, constant cp)
    T2_ = 300 * 10 ** (.4 / 1.4); T3_ = T2_ + 2800 / CP_AIR; T4_ = T3_ * 100 / 1000
    qo = CV_AIR * (T3_ - T4_) + CP_AIR * (T4_ - 300); eta16 = 1 - qo / 2800
    reg('c916', dict(P1=100, T1=300, P2=1000, q23=2800), 'T3', T3_, 1e-6); reg('c916', dict(P1=100, T1=300, P2=1000, q23=2800), 'eta', eta16, 1e-6)
    pr('9-16 T3', T3_, 3360, 3e-3, 'Cengel 9–16 (ans., 3 s.f.)'); pr('9-16 eta', eta16, 0.210, 3e-3, 'Cengel 9–16')
    MC(B('Chu trình không khí khép kín: 1-2 nén đẳng entropi 100 kPa, 27 °C → 1 MPa; 2-3 cấp nhiệt đẳng áp 2800 kJ/kg; 3-4 thải nhiệt đẳng tích về 100 kPa; 4-1 thải nhiệt đẳng áp về trạng thái đầu. Nhiệt dung riêng hằng (c_p = 1,005; c_v = 0,718). Nhiệt độ cực đại và hiệu suất nhiệt là:', 'A closed air cycle: 1-2 isentropic compression 100 kPa, 27 °C → 1 MPa; 2-3 constant-pressure heat addition of 2800 kJ/kg; 3-4 constant-volume heat rejection to 100 kPa; 4-1 constant-pressure heat rejection to the initial state. Constant specific heats (c_p = 1.005; c_v = 0.718). The maximum temperature and the thermal efficiency are:'),
       [sq(f'{N(T3_,0)} K và {N(eta16*100,1)} %', f'{N(T3_,0)} K and {N(eta16*100,1)} %'), sq(f'{N(300+2800/CP_AIR,0)} K và {N(eta16*100,1)} %', f'{N(300+2800/CP_AIR,0)} K and {N(eta16*100,1)} %'), sq(f'{N(T3_,0)} K và {N((1-1/10**(.4/1.4))*100,1)} %', f'{N(T3_,0)} K and {N((1-1/10**(.4/1.4))*100,1)} %'), sq(f'{N(T2_+2800/CV_AIR,0)} K và {N(eta16*100,1)} %', f'{N(T2_+2800/CV_AIR,0)} K and {N(eta16*100,1)} %')], 0,
       B(f'T₂ = 300·10^0,2857 = {N(T2_,1)} K; T₃ = T₂ + q/c_p = {N(T3_,0)} K (sách 3360 K). T₄ = T₃·(P₄/P₃) = {N(T4_,1)} K (v = const). q_out = c_v(T₃ − T₄) + c_p(T₄ − T₁) = {N(qo,1)} kJ/kg ⇒ η = 1 − {N(qo,1)}/2800 = {N(eta16,4)} (sách 21,0 %). Bỏ bước nén cho {N(300+2800/CP_AIR,0)} K; công thức Brayton 1 − 1/r_p^0,2857 cho {N((1-1/10**(.4/1.4))*100,1)} % không áp dụng vì chu trình này không phải Brayton; dùng c_v ở quá trình đẳng áp cho {N(T2_+2800/CV_AIR,0)} K.',
         f'T₂ = 300·10^0.2857 = {N(T2_,1)} K; T₃ = T₂ + q/c_p = {N(T3_,0)} K (book 3360 K). T₄ = T₃·(P₄/P₃) = {N(T4_,1)} K (v = const). q_out = c_v(T₃ − T₄) + c_p(T₄ − T₁) = {N(qo,1)} kJ/kg ⇒ η = 1 − {N(qo,1)}/2800 = {N(eta16,4)} (book 21.0 %). Skipping the compression gives {N(300+2800/CP_AIR,0)} K; the Brayton formula 1 − 1/r_p^0.2857 gives {N((1-1/10**(.4/1.4))*100,1)} % but this cycle is not a Brayton cycle; using c_v for the constant-pressure process gives {N(T2_+2800/CV_AIR,0)} K.'),
       3, T_OTHER, CP('9–16'), 'printed answer Cengel 9–16 + script')
    T2b = 300 * 10 ** (.4 / 1.4); T3b = T2b + 2.76 / 0.004 / CP_AIR; v1 = .287 * 300 / 100; v3 = .287 * T3b / 1000
    w31 = (1000 + 100) / 2 * (v1 - v3); q31 = CV_AIR * (300 - T3b) + w31; Qout19 = -q31 * 0.004
    Q19x = -(CV_AIR * (300 - T3b) + 2 * w31) * 0.004                  # trapezoid without the factor 1/2
    w12 = -CV_AIR * (T2b - 300); w23 = .287 * (T3b - T2b); eta19 = (w12 + w23 + w31) / (2.76 / 0.004)
    reg('c919', dict(T1=300, P1=100, P2=1000, m=0.004, Q23=2.76), 'Qout', Qout19, 1e-6); reg('c919', dict(T1=300, P1=100, P2=1000, m=0.004, Q23=2.76), 'eta', eta19, 1e-6)
    pr('9-19 Qout', Qout19, 1.679, 1e-3, 'Cengel 9–19'); pr('9-19 eta', eta19, 0.392, 1e-3, 'Cengel 9–19')
    MC(B('Chu trình không khí kín, 0,004 kg: 1-2 nén đẳng entropi 100 kPa, 27 °C → 1 MPa; 2-3 cấp nhiệt đẳng áp 2,76 kJ; 3-1 thải nhiệt theo đường thẳng P = c₁v + c₂ về trạng thái đầu. Nhiệt dung riêng hằng. Nhiệt thải (kJ) và hiệu suất là:', 'A closed air cycle, 0.004 kg: 1-2 isentropic compression 100 kPa, 27 °C → 1 MPa; 2-3 constant-pressure heat addition of 2.76 kJ; 3-1 heat rejection along the straight line P = c₁v + c₂ back to the initial state. Constant specific heats. The heat rejected (kJ) and the efficiency are:'),
       [sq(f'{N(Qout19,3)} kJ và {N(eta19*100,1)} %', f'{N(Qout19,3)} kJ and {N(eta19*100,1)} %'), sq(f'{N(Q19x,3)} kJ và {N((1-Q19x/2.76)*100,1)} %', f'{N(Q19x,3)} kJ and {N((1-Q19x/2.76)*100,1)} %'), sq(f'{N(Qout19,3)} kJ và {N((1-1/10**(.4/1.4))*100,1)} %', f'{N(Qout19,3)} kJ and {N((1-1/10**(.4/1.4))*100,1)} %'), sq(f'{N(2.76-Qout19,3)} kJ và {N(Qout19/2.76*100,1)} %', f'{N(2.76-Qout19,3)} kJ and {N(Qout19/2.76*100,1)} %')], 0,
       B(f'T₃ = T₂ + q/c_p = {N(T3b,1)} K; v₁ = {N(v1,3)}, v₃ = {N(v3,4)} m³/kg. Quá trình 3→1 là đường thẳng trên P–v: w₃₁ = (P₃ + P₁)/2·(v₁ − v₃) = {N(w31,1)} kJ/kg; q₃₁ = c_v(T₁ − T₃) + w₃₁ = {N(q31,1)} kJ/kg ⇒ Q_out = {N(Qout19,3)} kJ (sách 1,679); w_net = w₁₂ + w₂₃ + w₃₁ = {N(w12+w23+w31,1)} kJ/kg ⇒ η = {N(eta19,3)} (sách 39,2 %). Quên hệ số 1/2 của hình thang cho {N(Q19x,3)} kJ; {N(2.76-Qout19,3)} kJ là công thực.',
         f'T₃ = T₂ + q/c_p = {N(T3b,1)} K; v₁ = {N(v1,3)}, v₃ = {N(v3,4)} m³/kg. Process 3→1 is a straight line on P–v: w₃₁ = (P₃ + P₁)/2·(v₁ − v₃) = {N(w31,1)} kJ/kg; q₃₁ = c_v(T₁ − T₃) + w₃₁ = {N(q31,1)} kJ/kg ⇒ Q_out = {N(Qout19,3)} kJ (book 1.679); w_net = w₁₂ + w₂₃ + w₃₁ = {N(w12+w23+w31,1)} kJ/kg ⇒ η = {N(eta19,3)} (book 39.2 %). Forgetting the factor 1/2 of the trapezoid gives {N(Q19x,3)} kJ; {N(2.76-Qout19,3)} kJ is the net work.'),
       3, T_OTHER, CP('9–19'), 'printed answer Cengel 9–19 + script')

    # ---------------------------------------------------------------- 9-34 Otto variable cp (same type as Tutorials #1)
    o = otto_var(8, 300, 95, qin=750)
    for k_ in ('T3', 'P3', 'wnet', 'eta', 'mep'): reg('otto_v', dict(r=8, T1=300, P1=95, qin=750), k_, o[k_], 0.012)
    pr('9-34 P3', o['P3'], 3898, 3e-4, 'Cengel 9–34'); pr('9-34 T3', o['T3'], 1539, 3e-4, 'Cengel 9–34'); pr('9-34 wnet', o['wnet'], 392.4, 3e-4, 'Cengel 9–34'); pr('9-34 eta', o['eta'], 0.523, 2e-3, 'Cengel 9–34'); pr('9-34 MEP', o['mep'], 495, 2e-3, 'Cengel 9–34')
    MC(B('Chu trình Otto lý tưởng r = 8; không khí 95 kPa, 27 °C; nhiệt cấp đẳng tích 750 kJ/kg; nhiệt dung riêng thay đổi. Áp suất cực đại (kPa) và công thực (kJ/kg) lần lượt là:', 'An ideal Otto cycle, r = 8; air at 95 kPa and 27 °C; 750 kJ/kg of heat added at constant volume; variable specific heats. The maximum pressure (kPa) and the net work (kJ/kg) are, respectively:'),
       [sq(f'{N(o["P3"],0)} kPa và {N(o["wnet"],1)} kJ/kg', f'{N(o["P3"],0)} kPa and {N(o["wnet"],1)} kJ/kg'), sq(f'{N(o["P2"],0)} kPa và {N(o["wnet"],1)} kJ/kg', f'{N(o["P2"],0)} kPa and {N(o["wnet"],1)} kJ/kg'), sq(f'{N(o["P3"],0)} kPa và {N(o["qout"],1)} kJ/kg', f'{N(o["P3"],0)} kPa and {N(o["qout"],1)} kJ/kg'), sq(f'{N(o["P3"]/8,0)} kPa và {N(750*(1-8**-.4),1)} kJ/kg', f'{N(o["P3"]/8,0)} kPa and {N(750*(1-8**-.4),1)} kJ/kg')], 0,
       B(f'v_r2 = v_r1/8 ⇒ T₂ = {N(o["T2"],1)} K, u₂ = {N(o["u2"],1)}; u₃ = u₂ + 750 = {N(o["u3"],1)} ⇒ T₃ = {N(o["T3"],0)} K (sách 1539 K); P₃ = P₁·r·T₃/T₁ = 95·8·{N(o["T3"],0)}/300 = {N(o["P3"],0)} kPa (sách 3898). T₄ = {N(o["T4"],0)} K, q_out = u₄ − u₁ = {N(o["qout"],1)} ⇒ w_net = {N(o["wnet"],1)} kJ/kg (sách 392,4). {N(o["P2"],0)} kPa là P₂ (chưa cấp nhiệt); {N(o["qout"],1)} là q_out; cặp có {N(o["P3"]/8,0)} kPa lấy P₃/r và dùng η khí lạnh nhân q_in.',
         f'v_r2 = v_r1/8 ⇒ T₂ = {N(o["T2"],1)} K, u₂ = {N(o["u2"],1)}; u₃ = u₂ + 750 = {N(o["u3"],1)} ⇒ T₃ = {N(o["T3"],0)} K (book 1539 K); P₃ = P₁·r·T₃/T₁ = 95·8·{N(o["T3"],0)}/300 = {N(o["P3"],0)} kPa (book 3898). T₄ = {N(o["T4"],0)} K, q_out = u₄ − u₁ = {N(o["qout"],1)} ⇒ w_net = {N(o["wnet"],1)} kJ/kg (book 392.4). {N(o["P2"],0)} kPa is P₂ (before heat addition); {N(o["qout"],1)} is q_out; the pair with {N(o["P3"]/8,0)} kPa takes P₃/r and multiplies q_in by the cold-air η.'),
       3, T_OTTO, CP('9–34'), 'printed answer Cengel 9–34 + script')

    # ---------------------------------------------------------------- 9-59 Diesel engine (AF 24 in the statement, 25 reproduces the printed answers)
    def eng59(AF):
        cp_, cv_, k_ = 1.110, 0.823, 1.349; Vd = 4.5e-3 / 6; r = 17; V1 = Vd * r / (r - 1); m = 95 * V1 / (0.287 * 328)
        d = diesel(r, 328, 95, k=k_, cp=cp_, cv=cv_, qin=0.98 * 42500 / AF)
        W = m * d['wnet']; Pw = W * 6 * 2000 / 60 / 2; sfc = (m / AF * 6) * (2000 / 60 / 2) / Pw * 3600 * 1000
        return d, m, W, Pw, sfc, W / Vd
    d24, m24, W24, P24, s24, mep24 = eng59(24); d25, m25, W25, P25, s25, mep25 = eng59(25)
    for AF, (dd, mm, WW, PP, ss, me) in ((24, (d24, m24, W24, P24, s24, mep24)), (25, (d25, m25, W25, P25, s25, mep25))):
        p59 = dict(AF=AF)
        for nm_, val_ in (('T3', dd['T3']), ('rc', dd['rc']), ('eta', dd['eta']), ('Wcycle6', 6 * WW), ('mep', me), ('P', PP), ('sfc', ss)): reg('c959', p59, nm_, val_, 1e-5)
    pr('9-59 T3 (AF=25)', d25['T3'], 2383, 2e-4, 'Cengel 9–59 (ans.; reproduced with AF = 25 only)'); pr('9-59 rc (AF=25)', d25['rc'], 2.7, 1e-2, 'Cengel 9–59'); pr('9-59 W (AF=25)', 6 * W25, 4.36, 1e-3, 'Cengel 9–59'); pr('9-59 eta (AF=25)', d25['eta'], 0.543, 1e-3, 'Cengel 9–59')
    pr('9-59 MEP (AF=25)', mep25, 969, 3e-4, 'Cengel 9–59'); pr('9-59 P (AF=25)', P25, 72.7, 1e-3, 'Cengel 9–59'); pr('9-59 sfc (AF=25)', s25, 159, 3e-3, 'Cengel 9–59')
    MC(B('Động cơ Diesel 6 xi-lanh, 4 kỳ, 4,5 L, r = 17; không khí 95 kPa, 55 °C; nhiên liệu Q = 42 500 kJ/kg, tỉ lệ không khí–nhiên liệu 24, hiệu suất cháy 98 %; c_p = 1,110, c_v = 0,823 kJ/kg·K (k = 1,349) tại 850 K. Nhiệt độ cực đại là (đáp án in của sách 2383 K):', 'A six-cylinder, four-stroke, 4.5-L diesel engine, r = 17; air at 95 kPa and 55 °C; fuel Q = 42,500 kJ/kg, air–fuel ratio 24, combustion efficiency 98 %; c_p = 1.110, c_v = 0.823 kJ/kg·K (k = 1.349) at 850 K. The maximum temperature is (the book prints 2383 K):'),
       num(d24['T3'], [d25['T3'], 328 * 17 ** .4 + 0.98 * 42500 / 24 / 1.110, d24['T3'] - 273.15], 'K', 0), 0,
       B(f'q_in = ηc·HV/AF = 0,98·42 500/24 = {N(0.98*42500/24,1)} kJ/kg (không phụ thuộc khối lượng). T₂ = 328·17^0,349 = {N(d24["T2"],1)} K; T₃ = T₂ + q_in/c_p = {N(d24["T3"],0)} K; r_c = {N(d24["rc"],2)}. Đáp án in 2383 K, r_c = 2,7, 4,36 kJ, 0,543, 969 kPa, 72,7 kW, 159 g/kWh chỉ khớp khi AF = 25 (T₃ = {N(d25["T3"],0)} K): đề in 24, đáp án in tính với 25 (lỗi sách, ghi trong ghi chú). Dùng k = 1,4 cho T₂ cho {N(328*17**.4+0.98*42500/24/1.110,0)} K; {N(d24["T3"]-273.15,0)} là °C.',
         f'q_in = ηc·HV/AF = 0.98·42,500/24 = {N(0.98*42500/24,1)} kJ/kg (independent of the mass). T₂ = 328·17^0.349 = {N(d24["T2"],1)} K; T₃ = T₂ + q_in/c_p = {N(d24["T3"],0)} K; r_c = {N(d24["rc"],2)}. The printed answers 2383 K, r_c = 2.7, 4.36 kJ, 0.543, 969 kPa, 72.7 kW, 159 g/kWh are reproduced only with AF = 25 (T₃ = {N(d25["T3"],0)} K): the statement prints 24 but the answers were computed with 25 (book error, see the notes). Using k = 1.4 for T₂ gives {N(328*17**.4+0.98*42500/24/1.110,0)} K; {N(d24["T3"]-273.15,0)} is in °C.'),
       3, T_DIESEL, CP('9–59'), 'script; printed answers reproduce only with AF = 25 (notes)')
    ES(B('Cengel 9–59. Động cơ diesel 6 xi-lanh, 4 kỳ, 4,5 L, chu trình Diesel lý tưởng, r = 17. Không khí 95 kPa, 55 °C đầu nén, 2000 vòng/phút. Nhiên liệu Q_HV = 42 500 kJ/kg, tỉ lệ không khí–nhiên liệu 24, hiệu suất cháy 98 %. Dùng nhiệt dung riêng hằng tại 850 K (c_p = 1,110; c_v = 0,823; k = 1,349). Tính (a) T_max và r_c, (b) công thực mỗi chu trình và hiệu suất, (c) MEP, (d) công suất, (e) mức tiêu hao nhiên liệu riêng (g/kWh).', 'Cengel 9–59. Six-cylinder, four-stroke, 4.5-L diesel engine on the ideal diesel cycle, r = 17. Air at 95 kPa, 55 °C at the start of compression, 2000 rpm. Fuel Q_HV = 42,500 kJ/kg, air–fuel ratio 24, combustion efficiency 98 %. Constant specific heats at 850 K (c_p = 1.110; c_v = 0.823; k = 1.349). Determine (a) T_max and r_c, (b) the net work per cycle and the efficiency, (c) the MEP, (d) the power, (e) the specific fuel consumption (g/kWh).'),
       B(f'Giả thiết: khí-chuẩn, nhiệt dung riêng hằng; R = 0,287; 55 °C = 328 K; V_d = 4,5/6 = 0,75 L mỗi xi-lanh.\nV₁ = V_d·r/(r − 1) = {N(0.75e-3*17/16*1000,4)} L ⇒ m = P₁V₁/(RT₁) = {N(m24*1e3,4)} g/xi-lanh. q_in = ηc·Q_HV/AF = {N(0.98*42500/24,1)} kJ/kg (AF = 24).\nT₂ = T₁r^(k−1) = {N(d24["T2"],1)} K; T₃ = T₂ + q_in/c_p = {N(d24["T3"],0)} K; r_c = T₃/T₂ = {N(d24["rc"],3)}. T₄ = T₃(r_c/r)^(k−1) = {N(d24["T4"],0)} K; q_out = c_v(T₄ − T₁) = {N(d24["qout"],1)}; w_net = {N(d24["wnet"],1)} kJ/kg; η = {N(d24["eta"],4)}.\n(b) W_cycle (6 xi-lanh) = 6·m·w_net = {N(6*W24,3)} kJ. (c) MEP = W/V_d(xi-lanh) = {N(mep24,0)} kPa. (d) 4 kỳ: một chu trình mỗi 2 vòng ⇒ P = W_cycle·N/2 = {N(P24,1)} kW. (e) sfc = ṁ_f/P = {N(s24,1)} g/kWh.\n'
         f'SAI LỆCH NGUỒN: đề in AF = 24 nhưng các đáp án in (2383 K; 2,7; 4,36 kJ; 0,543; 969 kPa; 72,7 kW; 159 g/kWh) chỉ khớp khi AF = 25: T₃ = {N(d25["T3"],0)} K, r_c = {N(d25["rc"],2)}, W = {N(6*W25,2)} kJ, η = {N(d25["eta"],3)}, MEP = {N(mep25,0)} kPa, P = {N(P25,1)} kW, sfc = {N(s25,0)} g/kWh. Ở đây trả lời theo đề (AF = 24) và nêu cả hai. Hai đường: công thức đóng và tích phân ∮P dV số (verify_m02.py).',
         f'Assumptions: air-standard, constant specific heats; R = 0.287; 55 °C = 328 K; V_d = 4.5/6 = 0.75 L per cylinder.\nV₁ = V_d·r/(r − 1) = {N(0.75e-3*17/16*1000,4)} L ⇒ m = P₁V₁/(RT₁) = {N(m24*1e3,4)} g per cylinder. q_in = ηc·Q_HV/AF = {N(0.98*42500/24,1)} kJ/kg (AF = 24).\nT₂ = T₁r^(k−1) = {N(d24["T2"],1)} K; T₃ = T₂ + q_in/c_p = {N(d24["T3"],0)} K; r_c = T₃/T₂ = {N(d24["rc"],3)}. T₄ = T₃(r_c/r)^(k−1) = {N(d24["T4"],0)} K; q_out = c_v(T₄ − T₁) = {N(d24["qout"],1)}; w_net = {N(d24["wnet"],1)} kJ/kg; η = {N(d24["eta"],4)}.\n(b) W_cycle (6 cylinders) = 6·m·w_net = {N(6*W24,3)} kJ. (c) MEP = W/V_d(cylinder) = {N(mep24,0)} kPa. (d) Four-stroke: one cycle per 2 revolutions ⇒ P = W_cycle·N/2 = {N(P24,1)} kW. (e) sfc = ṁ_f/P = {N(s24,1)} g/kWh.\n'
         f'SOURCE DISCREPANCY: the statement prints AF = 24 but the printed answers (2383 K; 2.7; 4.36 kJ; 0.543; 969 kPa; 72.7 kW; 159 g/kWh) are reproduced only with AF = 25: T₃ = {N(d25["T3"],0)} K, r_c = {N(d25["rc"],2)}, W = {N(6*W25,2)} kJ, η = {N(d25["eta"],3)}, MEP = {N(mep25,0)} kPa, P = {N(P25,1)} kW, sfc = {N(s25,0)} g/kWh. Here we answer the statement as printed (AF = 24) and show both. Two routes: closed forms and numerical ∮P dV integration (verify_m02.py).'),
       3, T_DIESEL, CP('9–59'), 'script; printed answers reproduce only with AF = 25 (notes)')

    # ---------------------------------------------------------------- 9-76 Brayton mass flow
    b1 = brayton(12, 300, 1000); b2 = brayton(12, 300, 1000, etac=.85, etat=.85)
    for k_ in ('wnet', 'bwr', 'eta'): reg('brayton_k', dict(rp=12, T1=300, T3=1000, k=1.4, cp=CP_AIR, etac=1.0, etat=1.0, eps=0.0), k_, b1[k_], 1e-6); reg('brayton_k', dict(rp=12, T1=300, T3=1000, k=1.4, cp=CP_AIR, etac=.85, etat=.85, eps=0.0), k_, b2[k_], 1e-6)
    m1_, m2_ = 70e3 / b1['wnet'], 70e3 / b2['wnet']
    pr('9-76 (a)', m1_, 352, 2e-3, 'Cengel 9–76'); pr('9-76 (b)', m2_, 1037, 1e-3, 'Cengel 9–76')
    MC(B('Chu trình Brayton đơn giản: r_p = 12, T₁ = 300 K, T₃ = 1000 K, không khí c_p = 1,005, k = 1,4. Lưu lượng khí cần cho công suất 70 MW khi máy nén và tuabin có η = 100 % và khi cả hai có η = 85 % lần lượt là (kg/s):', 'A simple Brayton cycle: r_p = 12, T₁ = 300 K, T₃ = 1000 K, air c_p = 1.005, k = 1.4. The air flow required for 70 MW when the compressor and turbine have η = 100 % and when both have η = 85 % is, respectively (kg/s):'),
       [sq(f'{N(m1_,0)} và {N(m2_,0)}', f'{N(m1_,0)} and {N(m2_,0)}'), sq(f'{N(m2_,0)} và {N(m1_,0)}', f'{N(m2_,0)} and {N(m1_,0)}'), sq(f'{N(70e3/b1["wt"],0)} và {N(70e3/b2["wt"],0)}', f'{N(70e3/b1["wt"],0)} and {N(70e3/b2["wt"],0)}'), sq(f'{N(m1_,0)} và {N(70e3/(b1["wnet"]*.85),0)}', f'{N(m1_,0)} and {N(70e3/(b1["wnet"]*.85),0)}')], 0,
       B(f'x = 12^0,2857 = {N(12**(.4/1.4),4)}; lý tưởng: w_comp = c_pT₁(x − 1) = {N(b1["wc"],1)}, w_turb = c_pT₃(1 − 1/x) = {N(b1["wt"],1)}, w_net = {N(b1["wnet"],1)} kJ/kg ⇒ ṁ = 70 000/{N(b1["wnet"],1)} = {N(m1_,0)} kg/s (sách 352). Với η = 85 %: w_comp = {N(b2["wc"],1)}, w_turb = {N(b2["wt"],1)}, w_net = {N(b2["wnet"],1)} ⇒ ṁ = {N(m2_,0)} kg/s (sách 1037): công thực giảm gần 3 lần nên lưu lượng gấp 3. Chia cho w_turb thay w_net cho {N(70e3/b1["wt"],0)} và {N(70e3/b2["wt"],0)}; nhân η sau cùng cho {N(70e3/(b1["wnet"]*.85),0)}.',
         f'x = 12^0.2857 = {N(12**(.4/1.4),4)}; ideal: w_comp = c_pT₁(x − 1) = {N(b1["wc"],1)}, w_turb = c_pT₃(1 − 1/x) = {N(b1["wt"],1)}, w_net = {N(b1["wnet"],1)} kJ/kg ⇒ ṁ = 70,000/{N(b1["wnet"],1)} = {N(m1_,0)} kg/s (book 352). With η = 85 %: w_comp = {N(b2["wc"],1)}, w_turb = {N(b2["wt"],1)}, w_net = {N(b2["wnet"],1)} ⇒ ṁ = {N(m2_,0)} kg/s (book 1037): the net work falls almost threefold so the flow triples. Dividing by w_turb instead of w_net gives {N(70e3/b1["wt"],0)} and {N(70e3/b2["wt"],0)}; applying η to w_net only gives {N(70e3/(b1["wnet"]*.85),0)}.'),
       3, T_REAL, CP('9–76'), 'printed answer Cengel 9–76 + script')

    # ---------------------------------------------------------------- 9-84 real Brayton with turbine exit temperature given (variable cp)
    T1_ = 303.0
    h1 = A(T1_, 'h'); Pr1 = A(T1_, 'Pr'); T2s = Ainv('Pr', 12 * Pr1)['value']; wc84 = (A(T2s, 'h') - h1) / .82; h2 = h1 + wc84; h4 = A(773.15, 'h')
    def f84(T3):
        Pr3 = A(T3, 'Pr'); T4s = Ainv('Pr', Pr3 / 12)['value']; return (A(T3, 'h') - h4) - .88 * (A(T3, 'h') - A(T4s, 'h'))
    T3_84 = brentq(f84, 900, 1700); h3 = A(T3_84, 'h'); wt84 = h3 - h4; md = 100 / (0.287 * T1_) * 150 / 60; wn84 = wt84 - wc84; P84 = md * wn84; bwr84 = wc84 / wt84; eta84 = wn84 / (h3 - h2)
    p84 = dict(T1=303, rp=12, V1_m3min=150, T4a=773.15, etac=.82, etat=.88, P1=100)
    for nm_, val_ in (('T3', T3_84), ('wc', wc84), ('wt', wt84), ('P', P84), ('bwr', bwr84), ('eta', eta84)): reg('c984', p84, nm_, val_, 0.012)
    pr('9-84 P', P84, 659, 3e-3, 'Cengel 9–84 (T₁ = 303 K)'); pr('9-84 bwr', bwr84, 0.625, 2e-3, 'Cengel 9–84'); pr('9-84 eta', eta84, 0.319, 3e-3, 'Cengel 9–84')
    MC(B('Nhà máy tuabin khí Brayton đơn giản giữa 100 và 1200 kPa; không khí vào máy nén ở 30 °C, 150 m³/phút; ra tuabin ở 500 °C; η_c = 82 %, η_t = 88 %; nhiệt dung riêng thay đổi. Công suất thực (kW), tỉ số công hồi và hiệu suất là:', 'A simple Brayton gas-turbine plant between 100 and 1200 kPa; air enters the compressor at 30 °C at 150 m³/min and leaves the turbine at 500 °C; η_c = 82 %, η_t = 88 %; variable specific heats. The net power (kW), back work ratio and efficiency are:'),
       [sq(f'{N(P84,0)} kW; {N(bwr84,3)}; {N(eta84,3)}', f'{N(P84,0)} kW; {N(bwr84,3)}; {N(eta84,3)}'), sq(f'{N(P84*0.85,0)} kW; {N(bwr84,3)}; {N(eta84,3)}', f'{N(P84*0.85,0)} kW; {N(bwr84,3)}; {N(eta84,3)}'), sq(f'{N(P84,0)} kW; {N(1-bwr84,3)}; {N(eta84,3)}', f'{N(P84,0)} kW; {N(1-bwr84,3)}; {N(eta84,3)}'), sq(f'{N(P84,0)} kW; {N(bwr84,3)}; {N(1-1/12**(.4/1.4),3)}', f'{N(P84,0)} kW; {N(bwr84,3)}; {N(1-1/12**(.4/1.4),3)}')], 0,
       B(f'ṁ = ρ·V̇ = 100/(0,287·303)·150/60 = {N(md,3)} kg/s. Máy nén: T₂s = {N(T2s,1)} K ⇒ w_comp = (h₂s − h₁)/0,82 = {N(wc84,1)} kJ/kg. Tuabin: h₄a = h(773,15 K) = {N(h4,1)}; T₃ giải từ η_t = (h₃ − h₄a)/(h₃ − h₄s) ⇒ T₃ = {N(T3_84,0)} K, w_turb = {N(wt84,1)}. w_net = {N(wn84,1)} ⇒ Ẇ = {N(P84,0)} kW (sách 659); r_bw = {N(bwr84,3)} (0,625); η = w_net/(h₃ − h₂a) = {N(eta84,3)} (0,319). Giá trị {N(P84*0.85,0)} kW là công suất nhân nhầm 0,85; {N(1-bwr84,3)} là 1 − r_bw; {N(1-1/12**(.4/1.4),3)} là hiệu suất lý tưởng của r_p = 12.',
         f'ṁ = ρ·V̇ = 100/(0.287·303)·150/60 = {N(md,3)} kg/s. Compressor: T₂s = {N(T2s,1)} K ⇒ w_comp = (h₂s − h₁)/0.82 = {N(wc84,1)} kJ/kg. Turbine: h₄a = h(773.15 K) = {N(h4,1)}; T₃ follows from η_t = (h₃ − h₄a)/(h₃ − h₄s) ⇒ T₃ = {N(T3_84,0)} K, w_turb = {N(wt84,1)}. w_net = {N(wn84,1)} ⇒ Ẇ = {N(P84,0)} kW (book 659); r_bw = {N(bwr84,3)} (0.625); η = w_net/(h₃ − h₂a) = {N(eta84,3)} (0.319). {N(P84*0.85,0)} kW wrongly multiplies the power by 0.85; {N(1-bwr84,3)} is 1 − r_bw; {N(1-1/12**(.4/1.4),3)} is the ideal efficiency at r_p = 12.'),
       3, T_REAL, CP('9–84'), 'printed answer Cengel 9–84 + script')

    # ---------------------------------------------------------------- 9-96 / 9-98 regeneration with efficiencies (variable cp)
    r96 = brayton_var(7, 310, 1150, .75, .82, .65)
    for k_ in ('T4', 'wnet', 'eta'): reg('brayton_v', dict(rp=7, T1=310, T3=1150, etac=.75, etat=.82, eps=.65), k_, r96[k_], 0.012)
    pr('9-96 T4', r96['T4'], 783, 1e-3, 'Cengel 9–96'); pr('9-96 wnet', r96['wnet'], 108.1, 1e-3, 'Cengel 9–96'); pr('9-96 eta', r96['eta'], 0.225, 3e-3, 'Cengel 9–96')
    r96c = brayton(7, 310, 1150, etac=.75, etat=.82, eps=.65)
    MC(B('Chu trình Brayton có hồi nhiệt: r_p = 7, T_min = 310 K, T_max = 1150 K, η_c = 75 %, η_t = 82 %, ε = 65 %. Đề không nêu giả thiết nhiệt dung riêng; đáp án in (783 K; 108,1 kJ/kg; 22,5 %) khớp khi dùng bảng A-17. Nhiệt độ ra tuabin và hiệu suất theo bảng A-17 là:', 'A Brayton cycle with regeneration: r_p = 7, T_min = 310 K, T_max = 1150 K, η_c = 75 %, η_t = 82 %, ε = 65 %. The statement names no specific-heat assumption; the printed answers (783 K; 108.1 kJ/kg; 22.5 %) match Table A-17. The turbine-exit temperature and the efficiency from Table A-17 are:'),
       [sq(f'{N(r96["T4"],0)} K và {N(r96["eta"]*100,1)} %', f'{N(r96["T4"],0)} K and {N(r96["eta"]*100,1)} %'), sq(f'{N(r96c["T4"],0)} K và {N(r96c["eta"]*100,1)} %', f'{N(r96c["T4"],0)} K and {N(r96c["eta"]*100,1)} %'), sq(f'{N(r96["T4"],0)} K và {N(r96["wnet"]/(r96["h3"]-r96["h2"])*100,1)} %', f'{N(r96["T4"],0)} K and {N(r96["wnet"]/(r96["h3"]-r96["h2"])*100,1)} %'), sq(f'{N(r96["T5"] if "T5" in r96 else 0,0)} K và {N(r96["eta"]*100,1)} %', f'{N(r96["T5"] if "T5" in r96 else 0,0)} K and {N(r96["eta"]*100,1)} %')], 0,
       B(f'T₂s = {N(r96["T2s"],0)} K ⇒ w_comp = (h₂s − h₁)/0,75 = {N(r96["wc"],1)}; T₄s = {N(r96["T4s"],0)} K ⇒ w_turb = 0,82(h₃ − h₄s) = {N(r96["wt"],1)}; T₄ = {N(r96["T4"],0)} K (sách 783); h₅ = h₂ + 0,65(h₄ − h₂) = {N(r96["h5"],1)} ⇒ q_in = h₃ − h₅ = {N(r96["qin"],1)}; w_net = {N(r96["wnet"],1)} (sách 108,1) ⇒ η = {N(r96["eta"]*100,1)} %. Cp hằng 1,005 cho T₄ = {N(r96c["T4"],0)} K, η = {N(r96c["eta"]*100,1)} % (lệch 1 điểm %); bỏ hồi nhiệt trong q_in cho {N(r96["wnet"]/(r96["h3"]-r96["h2"])*100,1)} %.',
         f'T₂s = {N(r96["T2s"],0)} K ⇒ w_comp = (h₂s − h₁)/0.75 = {N(r96["wc"],1)}; T₄s = {N(r96["T4s"],0)} K ⇒ w_turb = 0.82(h₃ − h₄s) = {N(r96["wt"],1)}; T₄ = {N(r96["T4"],0)} K (book 783); h₅ = h₂ + 0.65(h₄ − h₂) = {N(r96["h5"],1)} ⇒ q_in = h₃ − h₅ = {N(r96["qin"],1)}; w_net = {N(r96["wnet"],1)} (book 108.1) ⇒ η = {N(r96["eta"]*100,1)} %. Constant c_p = 1.005 gives T₄ = {N(r96c["T4"],0)} K, η = {N(r96c["eta"]*100,1)} % (one percentage point off); leaving out the regenerator in q_in gives {N(r96["wnet"]/(r96["h3"]-r96["h2"])*100,1)} %.'),
       3, T_REGEN, CP('9–96'), 'printed answer Cengel 9–96 + script')
    r98 = brayton_var(8, 300, 1200, etat=.86, eps=.72, T2_given=580); qreg = r98['h5'] - r98['h2']
    for k_ in ('eta',): reg('brayton_v', dict(rp=8, T1=300, T3=1200, etat=.86, eps=.72, T2_given=580), k_, r98[k_], 0.012)
    reg('brayton_v', dict(rp=8, T1=300, T3=1200, etat=.86, eps=.72, T2_given=580), 'qreg', qreg, 0.012)
    pr('9-98 qreg', qreg, 152.5, 1e-3, 'Cengel 9–98'); pr('9-98 eta', r98['eta'], 0.360, 2e-3, 'Cengel 9–98')
    MC(B('Máy nén của động cơ tuabin khí có hồi nhiệt nén không khí từ 300 K, 100 kPa lên 800 kPa và 580 K (thực); ε = 72 %; không khí vào tuabin ở 1200 K; η_t = 86 %; nhiệt dung riêng thay đổi. Nhiệt trao đổi trong bộ hồi nhiệt (kJ/kg) và hiệu suất nhiệt là:', 'The compressor of a regenerative gas-turbine engine compresses air from 300 K, 100 kPa to 800 kPa and 580 K (actual); ε = 72 %; the turbine inlet is 1200 K; η_t = 86 %; variable specific heats. The heat transferred in the regenerator (kJ/kg) and the thermal efficiency are:'),
       [sq(f'{N(qreg,1)} kJ/kg và {N(r98["eta"]*100,1)} %', f'{N(qreg,1)} kJ/kg and {N(r98["eta"]*100,1)} %'), sq(f'{N(r98["h4"]-r98["h2"],1)} kJ/kg và {N(r98["eta"]*100,1)} %', f'{N(r98["h4"]-r98["h2"],1)} kJ/kg and {N(r98["eta"]*100,1)} %'), sq(f'{N(qreg,1)} kJ/kg và {N(r98["wnet"]/(r98["h3"]-r98["h2"])*100,1)} %', f'{N(qreg,1)} kJ/kg and {N(r98["wnet"]/(r98["h3"]-r98["h2"])*100,1)} %'), sq(f'{N((1-.72)*(r98["h4"]-r98["h2"]),1)} kJ/kg và {N(r98["eta"]*100,1)} %', f'{N((1-.72)*(r98["h4"]-r98["h2"]),1)} kJ/kg and {N(r98["eta"]*100,1)} %')], 0,
       B(f'h₂ = h(580 K) = {N(r98["h2"],1)}; w_turb = 0,86(h₃ − h₄s) = {N(r98["wt"],1)} ⇒ h₄ = {N(r98["h4"],1)}; q_regen = ε(h₄ − h₂) = {N(qreg,1)} kJ/kg (sách 152,5); h₅ = {N(r98["h5"],1)}; q_in = h₃ − h₅ = {N(r98["qin"],1)}; w_net = {N(r98["wnet"],1)} ⇒ η = {N(r98["eta"],3)} (sách 36,0 %). {N(r98["h4"]-r98["h2"],1)} là q_regen,max (ε = 1); bỏ hồi nhiệt trong q_in cho {N(r98["wnet"]/(r98["h3"]-r98["h2"])*100,1)} %; dùng (1 − ε) thay ε cho {N((1-.72)*(r98["h4"]-r98["h2"]),1)}.',
         f'h₂ = h(580 K) = {N(r98["h2"],1)}; w_turb = 0.86(h₃ − h₄s) = {N(r98["wt"],1)} ⇒ h₄ = {N(r98["h4"],1)}; q_regen = ε(h₄ − h₂) = {N(qreg,1)} kJ/kg (book 152.5); h₅ = {N(r98["h5"],1)}; q_in = h₃ − h₅ = {N(r98["qin"],1)}; w_net = {N(r98["wnet"],1)} ⇒ η = {N(r98["eta"],3)} (book 36.0 %). {N(r98["h4"]-r98["h2"],1)} is q_regen,max (ε = 1); leaving out the regenerator in q_in gives {N(r98["wnet"]/(r98["h3"]-r98["h2"])*100,1)} %; using (1 − ε) instead of ε gives {N((1-.72)*(r98["h4"]-r98["h2"]),1)}.'),
       3, T_REGEN, CP('9–98'), 'printed answer Cengel 9–98 + script')

    # ---------------------------------------------------------------- 9-110, 9-150 multistage
    m110 = multistage_var(9, 2, 300, 1200); mdot110 = 110e3 / m110['wnet']
    for k_ in ('wc', 'wt', 'wnet'): reg('multi_v', dict(rp=9, N=2, T1=300, T3=1200, eps=0), k_, m110[k_], 0.012)
    reg('multi_v', dict(rp=9, N=2, T1=300, T3=1200, eps=0), 'mdot110', mdot110, 0.012)
    pr('9-110 mdot', mdot110, 250, 3e-3, 'Cengel 9–110')
    MC(B('Nhà máy tuabin khí hai cấp nén và hai cấp giãn, tỉ số áp tổng 9, không khí vào mỗi cấp nén ở 300 K và mỗi cấp tuabin ở 1200 K, nhiệt dung riêng thay đổi. Lưu lượng khí tối thiểu cho công suất thực 110 MW (kg/s) là (chia đều tỉ số áp cho các cấp):', 'A gas-turbine plant with two compression and two expansion stages, overall pressure ratio 9, air entering each compressor stage at 300 K and each turbine stage at 1200 K, variable specific heats. The minimum air flow for a net power of 110 MW (kg/s) is (equal pressure ratio in every stage):'),
       num(mdot110, [110e3 / (m110['wt']), 110e3 / (brayton_var(9, 300, 1200)['wnet']), 110e3 / (m110['wnet'] * 2)], 'kg/s', 0), 0,
       B(f'Mỗi cấp √9 = 3: T₂ = {N(m110["T2"],1)} K, h₂ = {N(m110["h2"],1)}; T₇ = {N(m110["T7"],1)} K, h₇ = {N(m110["h7"],1)}. w_comp = 2(h₂ − h₁) = {N(m110["wc"],1)}; w_turb = 2(h₆ − h₇) = {N(m110["wt"],1)}; w_net = {N(m110["wnet"],1)} kJ/kg ⇒ ṁ = 110 000/{N(m110["wnet"],1)} = {N(mdot110,0)} kg/s (sách 250). Chia cho w_turb: {N(110e3/m110["wt"],0)}; chu trình một cấp (w_net = {N(brayton_var(9,300,1200)["wnet"],1)}) cho {N(110e3/(brayton_var(9,300,1200)["wnet"]),0)}: hai cấp có công thực lớn hơn nên cần ít khí hơn. Hồi nhiệt không đổi công thực.',
         f'Each stage √9 = 3: T₂ = {N(m110["T2"],1)} K, h₂ = {N(m110["h2"],1)}; T₇ = {N(m110["T7"],1)} K, h₇ = {N(m110["h7"],1)}. w_comp = 2(h₂ − h₁) = {N(m110["wc"],1)}; w_turb = 2(h₆ − h₇) = {N(m110["wt"],1)}; w_net = {N(m110["wnet"],1)} kJ/kg ⇒ ṁ = 110,000/{N(m110["wnet"],1)} = {N(mdot110,0)} kg/s (book 250). Dividing by w_turb gives {N(110e3/m110["wt"],0)}; the single-stage cycle (w_net = {N(brayton_var(9,300,1200)["wnet"],1)}) gives {N(110e3/(brayton_var(9,300,1200)["wnet"]),0)}: the two-stage cycle has more net work and needs less air. Regeneration does not change the net work.'),
       3, T_MULTI, CP('9–110'), 'printed answer Cengel 9–110 + script')
    m150 = multistage_k(3.5 ** 2, 2, 300, 1200, etac=.78, etat=.86, eps=.72)
    for k_ in ('wc', 'wt', 'bwr', 'eta'): reg('multi_k', dict(rp=3.5 ** 2, N=2, T1=300, T3=1200, etac=.78, etat=.86, eps=.72, k=1.4, cp=CP_AIR), k_, m150[k_], 1e-6)
    pr('9-150 bwr', m150['bwr'], 0.532, 3e-3, 'Cengel 9–150'); pr('9-150 eta', m150['eta'], 0.392, 2e-3, 'Cengel 9–150')
    MC(B('Động cơ tuabin khí hồi nhiệt, hai cấp nén và hai cấp giãn, tỉ số áp mỗi cấp 3,5; không khí vào mỗi cấp nén 300 K và mỗi cấp tuabin 1200 K; η_c = 78 %, η_t = 86 %, ε = 72 %; c_p = 1,005, k = 1,4. Tỉ số công hồi và hiệu suất là:', 'A regenerative gas-turbine engine with two compression and two expansion stages, pressure ratio 3.5 per stage; air enters each compressor stage at 300 K and each turbine stage at 1200 K; η_c = 78 %, η_t = 86 %, ε = 72 %; c_p = 1.005, k = 1.4. The back work ratio and the efficiency are:'),
       [sq(f'{N(m150["bwr"],3)} và {N(m150["eta"],3)}', f'{N(m150["bwr"],3)} and {N(m150["eta"],3)}'), sq(f'{N(m150["bwr"],3)} và {N(multistage_k(3.5**2,2,300,1200,etac=.78,etat=.86,eps=0)["eta"],3)}', f'{N(m150["bwr"],3)} and {N(multistage_k(3.5**2,2,300,1200,etac=.78,etat=.86,eps=0)["eta"],3)}'), sq(f'{N(multistage_k(3.5**2,2,300,1200)["bwr"],3)} và {N(m150["eta"],3)}', f'{N(multistage_k(3.5**2,2,300,1200)["bwr"],3)} and {N(m150["eta"],3)}'), sq(f'{N(m150["bwr"],3)} và {N(m150["wnet"]/(CP_AIR*(1200-m150["T5"])),3)}', f'{N(m150["bwr"],3)} and {N(m150["wnet"]/(CP_AIR*(1200-m150["T5"])),3)}')], 0,
       B(f'x = 3,5^0,2857 = {N(3.5**(.4/1.4),4)}; w_comp = 2c_pT₁(x − 1)/0,78 = {N(m150["wc"],1)}; w_turb = 2·0,86·c_pT₃(1 − 1/x) = {N(m150["wt"],1)} ⇒ r_bw = {N(m150["bwr"],3)} (sách 53,2 %). T₂ = {N(m150["T2"],1)} K, T₄ = {N(m150["T4"],1)} K; T₅ = T₂ + 0,72(T₄ − T₂) = {N(m150["T5"],1)} K; q_in = c_p(T₃ − T₅) + c_p(T₃ − T₄) = {N(m150["qin"],1)}; w_net = {N(m150["wnet"],1)} ⇒ η = {N(m150["eta"],3)} (sách 39,2 %). Không hồi nhiệt η = {N(multistage_k(3.5**2,2,300,1200,etac=.78,etat=.86,eps=0)["eta"],3)}; bỏ η_c, η_t: r_bw = {N(multistage_k(3.5**2,2,300,1200)["bwr"],3)}; quên nhiệt hâm nóng trong q_in cho η = {N(m150["wnet"]/(CP_AIR*(1200-m150["T5"])),3)}.',
         f'x = 3.5^0.2857 = {N(3.5**(.4/1.4),4)}; w_comp = 2c_pT₁(x − 1)/0.78 = {N(m150["wc"],1)}; w_turb = 2·0.86·c_pT₃(1 − 1/x) = {N(m150["wt"],1)} ⇒ r_bw = {N(m150["bwr"],3)} (book 53.2 %). T₂ = {N(m150["T2"],1)} K, T₄ = {N(m150["T4"],1)} K; T₅ = T₂ + 0.72(T₄ − T₂) = {N(m150["T5"],1)} K; q_in = c_p(T₃ − T₅) + c_p(T₃ − T₄) = {N(m150["qin"],1)}; w_net = {N(m150["wnet"],1)} ⇒ η = {N(m150["eta"],3)} (book 39.2 %). Without regeneration η = {N(multistage_k(3.5**2,2,300,1200,etac=.78,etat=.86,eps=0)["eta"],3)}; ignoring η_c, η_t: r_bw = {N(multistage_k(3.5**2,2,300,1200)["bwr"],3)}; forgetting the reheat heat in q_in gives η = {N(m150["wnet"]/(CP_AIR*(1200-m150["T5"])),3)}.'),
       3, T_MULTI, CP('9–150'), 'printed answer Cengel 9–150 + script')

    # ---------------------------------------------------------------- 9-119 static turbojet (variable cp); 9-147
    j = jet_static_var(12, 300, 95, 10, 0.2, 42700); jc = None
    for k_ in ('T3', 'T4', 'T5', 'V', 'F'): reg('jet_static', dict(rp=12, T1=300, P1=95, m=10, mf=0.2, HV=42700), k_, j[k_], 0.012)
    pr('9-119 F', j['F'], 9089, 1e-3, 'Cengel 9–119 (A-17; statement names no cp assumption)')
    k_, cp_ = 1.4, 1.005; T2c = 300 * 12 ** ((k_ - 1) / k_); T3c = T2c + .2 * 42700 / 10 / cp_; T4c = T3c - (T2c - 300); P4c = 95 * 12 * (T4c / T3c) ** (k_ / (k_ - 1)); T5c = T4c * (95 / P4c) ** ((k_ - 1) / k_); Fc = 10 * math.sqrt(2000 * cp_ * (T4c - T5c))
    MC(B('Turbojet đứng yên trên mặt đất (bị phanh giữ): r_p = 12, không khí 27 °C, 95 kPa, 10 kg/s; nhiên liệu 42 700 kJ/kg cháy hết với lưu lượng 0,2 kg/s; bỏ qua bộ khuếch tán, hiệu suất các bộ phận và phần tăng khối lượng ở cửa ra. Đề không nêu nhiệt dung riêng: dùng bảng A-17. Lực phanh cần giữ máy bay là:', 'A turbojet held stationary on the ground by its brakes: r_p = 12, air at 27 °C, 95 kPa, 10 kg/s; fuel of 42,700 kJ/kg burnt completely at 0.2 kg/s; neglect the diffuser, component inefficiencies and the small mass increase at the exit. The statement names no specific-heat assumption: use Table A-17. The brake force needed is:'),
       num(j['F'], [Fc, 10 * j['V'] * 1.02, 0.2 * 42700 / (j['V'] / 1000)], 'N', 0), 0,
       B(f'q = ṁ_fQ_R/ṁ = {N(0.2*42700/10,1)} kJ/kg. T₂ = {N(j["T2"],0)} K (P_r); T₃ từ h₃ = h₂ + q ⇒ {N(j["T3"],0)} K; công tuabin = công nén ⇒ h₄ = h₃ − (h₂ − h₁) ⇒ T₄ = {N(j["T4"],0)} K, P₄ = {N(j["P4"],0)} kPa; vòi phun giãn tới 95 kPa: T₅ = {N(j["T5"],0)} K, V = √[2(h₄ − h₅)] = {N(j["V"],0)} m/s; F = ṁV = {N(j["F"],0)} N (sách 9089). Cp hằng 1,005 cho {N(Fc,0)} N (cao hơn 2,5 %); thêm ṁ_f vào lưu lượng cho {N(10*j["V"]*1.02,0)} N.',
         f'q = ṁ_fQ_R/ṁ = {N(0.2*42700/10,1)} kJ/kg. T₂ = {N(j["T2"],0)} K (P_r); T₃ from h₃ = h₂ + q ⇒ {N(j["T3"],0)} K; turbine work = compressor work ⇒ h₄ = h₃ − (h₂ − h₁) ⇒ T₄ = {N(j["T4"],0)} K, P₄ = {N(j["P4"],0)} kPa; the nozzle expands to 95 kPa: T₅ = {N(j["T5"],0)} K, V = √[2(h₄ − h₅)] = {N(j["V"],0)} m/s; F = ṁV = {N(j["F"],0)} N (book 9089). Constant c_p = 1.005 gives {N(Fc,0)} N (2.5 % higher); adding ṁ_f to the flow gives {N(10*j["V"]*1.02,0)} N.'),
       3, T_JET, CP('9–119'), 'printed answer Cengel 9–119 (A-17 reproduces it) + script')
    b6 = brayton_var(6, 300, 1300); b12 = brayton_var(12, 300, 1300)
    for rp_, bb in ((6, b6), (12, b12)):
        for k_ in ('wnet', 'eta'): reg('brayton_v', dict(rp=rp_, T1=300, T3=1300), k_, bb[k_], 0.012)
    dw, de = b12['wnet'] - b6['wnet'], b12['eta'] - b6['eta']
    pr('9-147 dw', dw, 41.5, 3e-3, 'Cengel 9–147'); pr('9-147 deta', de, 0.106, 6e-3, 'Cengel 9–147')
    MC(B('Chu trình Brayton đơn giản, T_min = 300 K, T_max = 1300 K, nhiệt dung riêng thay đổi. Tăng gấp đôi tỉ số áp từ 6 lên 12 (giữ nguyên hai nhiệt độ). Công thực riêng và hiệu suất thay đổi lần lượt là:', 'A simple Brayton cycle, T_min = 300 K, T_max = 1300 K, variable specific heats. The pressure ratio is doubled from 6 to 12 (both temperatures unchanged). The net work per kg and the efficiency change by, respectively:'),
       [sq(f'công +{N(dw,1)} kJ/kg, hiệu suất +{N(de*100,1)} điểm %', f'work +{N(dw,1)} kJ/kg, efficiency +{N(de*100,1)} percentage points'), sq(f'công −{N(dw,1)} kJ/kg, hiệu suất +{N(de*100,1)} điểm %', f'work −{N(dw,1)} kJ/kg, efficiency +{N(de*100,1)} percentage points'), sq(f'công +{N(dw,1)} kJ/kg, hiệu suất −{N(de*100,1)} điểm %', f'work +{N(dw,1)} kJ/kg, efficiency −{N(de*100,1)} percentage points'), sq(f'công +{N(dw*2,1)} kJ/kg, hiệu suất +{N(de*200,1)} điểm %', f'work +{N(dw*2,1)} kJ/kg, efficiency +{N(de*200,1)} percentage points')], 0,
       B(f'r_p = 6: w_net = {N(b6["wnet"],1)} kJ/kg, η = {N(b6["eta"],3)}; r_p = 12: w_net = {N(b12["wnet"],1)} kJ/kg, η = {N(b12["eta"],3)}. Hiệu: Δw = +{N(dw,1)} kJ/kg (sách 41,5), Δη = +{N(de*100,1)} điểm % (sách 10,6). Với T_max/T_min = 4,33 (khí lạnh) r_p tối ưu cho công là 4,33^1,75 ≈ 13, nên cả 6 và 12 đều nằm dưới điểm tối ưu: công và hiệu suất cùng tăng. Công giảm hoặc hiệu suất giảm chỉ xảy ra khi vượt r_p,opt; gấp đôi các số chênh là nhầm nhân hai.',
         f'r_p = 6: w_net = {N(b6["wnet"],1)} kJ/kg, η = {N(b6["eta"],3)}; r_p = 12: w_net = {N(b12["wnet"],1)} kJ/kg, η = {N(b12["eta"],3)}. Differences: Δw = +{N(dw,1)} kJ/kg (book 41.5), Δη = +{N(de*100,1)} percentage points (book 10.6). With T_max/T_min = 4.33 (cold air) the work-optimal r_p is 4.33^1.75 ≈ 13, so both 6 and 12 lie below the optimum: work and efficiency both rise. A fall in work or efficiency would occur only beyond r_p,opt; doubling the differences is a factor-two slip.'),
       3, T_BRAY, CP('9–147'), 'printed answer Cengel 9–147 + script')
    return G.ITEMS, G.PRINTED

